    main.innerHTML=`<ul class="ds-stats">${stat('Physical on hand',kg(state.products.reduce((n,p)=>n+p.onHand,0)),'Includes inputs, held material, WIP and recovery')}${stat('Reserved',kg(state.orders.reduce((n,o)=>n+o.lines.reduce((v,l)=>v+l.reserved,0),0)),'Specific units held for order balances')}${stat('Free released stock',kg(state.products.reduce((n,p)=>n+available(p.sku),0)),'Eligible physical units less reservations')}${stat('Unavailable material',kg(state.products.reduce((n,p)=>n+store.unavailable(p.sku),0)),'Quality, WIP, transit and recovery')}</ul><div class="ds-demo__line"><p class="ds-small ds-muted">Actual kg · Dimensions in mm · All values fictional</p><div class="ds-demo__actions">${link('Receive material',url('receipts'),'primary','plus')}${link('QC queue',url('inspection'))}${link('Full ledger',url('ledger'))}</div></div>${table('stock-table','Stock variants',['Product','Specification','On hand','Reserved','Unavailable','Free stock','Action'],list.map(p=>[primary(p.sku,p.name+' · '+p.materialClass,url('lots','sku='+p.sku)),primary(p.grade+' · '+p.finish,p.size),{html:kg(p.onHand),sort:p.onHand},{html:kg(reserved(p.sku)),sort:reserved(p.sku)},{html:kg(store.unavailable(p.sku)),sort:store.unavailable(p.sku)},{html:kg(available(p.sku)),sort:available(p.sku)},link('Material units',url('lots','sku='+p.sku),'ghost','arrow-right')]),{search:true,pageSize:true,filter:params.get('q')||'',tools:select('family-filter','Product family',[['All families','All families'],...[...new Set(state.products.map(p=>p.family))].map(x=>[x,x])],family,'data-ds-filter-family')})}${alert('Receipt is separate from release','New material enters quarantine. Record inspection evidence before allocating it. Reservations do not reduce physical stock; gate-cleared transit posts a single stock issue.')}`;
